    "description": "日前，国家外汇管理局发放最新一批合格境内机构投资者（QDII）额度后，近日，银行理财子公司集中发行一批以美元理财产品为主的跨境理财产品，并开启新一轮产品营销。中国理财网信息显示，截至9月10日，近期新发行（包括处于待售和募集状态的银行理财产品）23只名称中带有“美元”字样的银行理财产品，涉及12家银行理财子公司或合资理财公司、1家银行。（证券日报）",
