    "content": "9月10日，*ST清越（688496.SH）以跌停价0.58元报收，跌幅20.55%，总市值仅约2.61亿元。至此，公司股票已连续20个交易日每日收盘价均低于1元，触及《上海证券交易所科创板股票上市规则》规定的交易类强制退市情形。公司当日公告称，股票自9月11日开市起停牌。 根据规则，交易类强制退市公司股票不进入退市整理期，上交所将在公告终止上市决定后5个交易日内对公司股票予以摘牌。 公开资料显示，清越科技成立于2010年，是一家为物联网终端显示提供整体解决方案的供应商，主要从事OLED等新型显示器件的研发、生产和…"
