    "description": "9月10日，记者跟随“活力中国调研行”采访团来到河南省鹤壁市浚县伾山街道西杨玘屯村，探访当地泥塑产业发展情况。近年来，当地年轻泥塑艺人在传承传统制作技艺的基础上，不断融入现代创意，推出会唱歌的泥咕咕、可转动解压类泥塑作品，让传统泥塑走进年轻群体和现代生活。",
    "content": "9月10日，记者跟随“活力中国调研行”采访团来到河南省鹤壁市浚县伾山街道西杨玘屯村，探访当地泥塑产业发展情况。近年来，当地年轻泥塑艺人在传承传统制作技艺的基础上，不断融入现代创意，推出会唱歌的泥咕咕、可转动解压类泥塑作品，让传统泥塑走进年轻群体和现代生活。"
