    "description": "36氪获悉，中信建投证券研报称，集运方面，运输市场总体稳定，不同航线走势分化。综合指数连续六周上涨，各航线受区域供需与地缘因素影响涨跌互现。北美航线在旺季备货与巴拿马运河限流支撑下温和上行，美西涨幅略高于美东；欧洲及地中海航线运输需求基本稳定，市场运价继续回落；南美航线需求平稳增长，推动运价上涨；亚洲内航线在旺季补货带动下整体上行。油运方面，本周国际油运市场延续高位运行。",
