    "pub_date": "2026-09-11 08:04:52",
    "author": "",
    "description": "9月10日，瑞丰银行发放2026年中期现金红利1.96亿元，是今年首家派发中期“红包”的A股上市银行。至此，包括瑞丰银行在内，已有20家A股上市银行披露或实施2026年中期利润分配方案，合计拟派息2661.14亿元。其中，国有大行分红总额占比超八成，且集体拟提升分红比例至31%。业内人士认为，下一步，上市银行在不断提升投资者获得感的同时，分红政策也应与宏观经济环境、监管导向及自身经营实际的变化动态适配。（中证报）",
