    "author": "齐志明/人民日报",
    "description": "“转人工！转人工！”屏幕上，江苏徐州消费者吴女士连续发送指令，对话框弹回的依然是AI（人工智能）客服的“亲，我理解您的心情”——后面跟着一串标准化菜单。折腾一个多小时后终于接通人工，三两句就把退货诉求说清了，吴女士哭笑不得：“太费劲了。” 近年来，AI客服快速嵌入电商、通信、金融、出行、家电等众多消费场景，在提升响应效率、降低运营成本方面发挥了积极作用。然而，本应为服务赋能的技术，在一些平台却成了答非所问、循环套话、转人工难的“拦路虎”…",
