    "content": "新华社渥太华9月10日电（记者林威）加拿大总理马克·卡尼10日在艾伯塔省卡尔加里市与到访的乌克兰总统泽连斯基举行会晤。双方决定合作扩大军用无人机生产，并宣布达成一系列新协议。 根据加总理办公室发布的新闻稿，加拿大将建立一个军用无人机全国性数字平台，以乌克兰“勇敢一号”无人机平台为蓝本，加快无人机及反无人机系统研发、采购和部署，保障加军及海岸警卫队的装备供应。加方已签署首批价值5000万加元（约3615万美元）的采购合同。 此外，双方签署了《加乌百年伙伴关系宣言》以及加强国防与安全合作的联合宣言。加方宣布多项对乌援助…"
