    "author": "刘杰,Leo Pedro",
    "description": "新华社马普托9月10日电（记者刘杰）据莫桑比克通讯社10日报道，莫桑比克中部马尼卡省一处金矿当天凌晨发生坍塌，造成至少6人死亡，搜救工作仍在进行。 报道说，事故发生在马尼卡省万杜济区塞斯卡罗斯地区，一批手工采金者进入矿井开采黄金，随后矿井坍塌，多人被埋。 马尼卡省警方发言人莫西尼奥·马纳塞说，目前已找到6名遇难者遗体，根据现场情况判断，可能还有人员被困井下。过去两天，当地出现降雨，土壤湿度增加可能是矿井坍塌的原因之一。 报道说，当地禁止…",
    "content": "新华社马普托9月10日电（记者刘杰）据莫桑比克通讯社10日报道，莫桑比克中部马尼卡省一处金矿当天凌晨发生坍塌，造成至少6人死亡，搜救工作仍在进行。 报道说，事故发生在马尼卡省万杜济区塞斯卡罗斯地区，一批手工采金者进入矿井开采黄金，随后矿井坍塌，多人被埋。 马尼卡省警方发言人莫西尼奥·马纳塞说，目前已找到6名遇难者遗体，根据现场情况判断，可能还有人员被困井下。过去两天，当地出现降雨，土壤湿度增加可能是矿井坍塌的原因之一。 报道说，当地禁止采金，但仍有人夜间进入矿区非法开采。目前估计有上万人聚集在塞斯卡罗斯地区非法采金…"
