    "content": "新华社耶路撒冷9月10日电（记者冯国芮 王卓伦）以色列总理内塔尼亚胡和国防部长卡茨10日晚发表联合声明说，以军当天摧毁了黎巴嫩南部阿里塔希尔高地之下的黎真主党地下设施。以色列国防军当晚发表声明说，以军爆破时使用超过1100吨炸药。 以军称，这些地下设施属于负责黎南部利塔尼河以北地区的真主党巴德尔部队。地道网络共有8条通道，总长度5.4公里，是该部队的“神经中枢”。 以军称，在地道内发现了数十枚伊朗制造的火箭弹、导弹和无人机，以及枪支、反坦克导弹、数百枚地雷和其他爆炸物。以军还称，这些地下设施历时约20年建成，由伊朗…"
