    "content": "新华社纽约9月10日电 纽约股市三大股指10日下跌。 截至当天收盘，道琼斯工业平均指数比前一交易日下跌316.56点，收于52064.10点，跌幅为0.60%；标准普尔500种股票指数下跌44.66点，收于7591.70点，跌幅为0.58%；纳斯达克综合指数下跌171.62点，收于26081.72点，跌幅为0.65%。 板块方面，标普500指数十一大板块九跌二涨。材料板块和公用事业板块分别以1.48%和1.00%的跌幅领跌，通信服务板块和必需消费品板块分别上涨0.25%和0.24%。"
