    "content": "新华社科威特城9月10日电（记者尹炣）亚丁消息：也门政府官员10日说，在政府海军部队撤出红海战略要地哈尼什群岛后，也门胡塞武装已在岛上部署兵力。当晚，也门政府军将该国西海岸一片区域划定为“作战区”。 这名匿名政府官员告诉新华社记者，也门政府海军部队10日下午撤出哈尼什群岛后，胡塞武装随即进入，并在岛上建立军事阵地。 哈尼什群岛位于曼德海峡以北，靠近国际主要航运通道，具有监控和保障海上交通安全的重要战略价值。 同一天，在经历数小时激烈交火后，胡塞武装攻占也门西南部塔伊兹省战略要地、红海港口城市穆哈，政府军被迫向南撤至…"
