    "content": "新华社墨西哥城9月10日电（记者翟淑睿）针对美方批评墨西哥打击贩毒行动的言论，墨西哥总统辛鲍姆10日表示，美国不应把墨西哥作为其选举政治的工具。 辛鲍姆在总统府例行记者会上说，美国将于11月举行国会中期选举，“不要在选举活动中利用墨西哥”。墨西哥不介入美国选举进程，“他们也不应该介入墨西哥”。 辛鲍姆强调，美国应解决自身的毒品消费问题并遏制武器贩往墨西哥。墨美应在相互尊重的基础上开展合作，双方关系应建立在“协调而非从属”的基础上。 美国国务卿鲁比奥9日在访问厄瓜多尔期间声称，墨西哥打击贩毒集团的行动“远远不够”，该…"
