    "content": "新华社拉姆安拉9月10日电（记者赵伟宏）巴勒斯坦民族解放运动（法塔赫）中央委员会秘书长贾布里勒·拉朱卜10日晚表示，对11月如期举行巴勒斯坦立法委员会选举持怀疑态度，并呼吁在选举前先进行全国对话，就选举机制达成共识。 拉朱卜当天在约旦河西岸中部城市拉姆安拉接受媒体采访时说，目前迹象表明，11月28日举行立法委员会选举并不可行，但选举过去是、现在依然是巴勒斯坦的战略选择和通往执政的途径。 拉朱卜强调，在推进选举前，必须进行全面的全国对话以就选举机制达成一致。他指出，如果缺乏民族团结和内部改革的框架，巴勒斯坦人将继续陷…"
