    "content": "新华社天津9月10日电（记者周润健）记者从交通运输部北海航海保障中心获悉，由中心牵头实施的全国首套S-122海上保护区专题数据集近日编制完成，并顺利通过船载终端加载测试。这一成果将海洋保护区法定管控边界转化为标准化航海数据，推动生态保护法规从纸面落到船舶航行一线。 S-100是国际通用海道测量数据标准体系，相当于海上空间信息的“通用语言”，按照这个标准制作的数据，可在各类合规船载导航终端上识别、展示。S-122作为这个体系下的特色专题数据集，专门承载海上保护区相关信息。 交通运输部北海航海保障中心海事测绘处副处长邬…"
