    "content": "新华社呼和浩特9月10日电（记者韩佳诺）推动乡村振兴，人才是关键。2025年，我国农民教育培训工作扎实推进，全国农广校体系开展农业农村实用技术培训超千万人次。 记者是在9月9日至10日于内蒙古呼和浩特举办的第八届全国农民教育培训发展论坛上了解到上述信息的。 据了解，高素质农民指的是有文化、懂技术、善经营、会管理的乡村人才，是推动农业现代化和乡村振兴的关键力量。 专家表示，2025年我国农民教育培训、乡村文化体育和高素质农民发展取得了积极进展；全国培育高素质农民61.36万人；完成学用贯通综合试点任务，累计培育1.1…"
