    "pub_date": "2026-09-11 02:24:58",
    "author": "刘方强",
    "description": "新华社亚的斯亚贝巴9月10日电（记者刘方强）由中国土木工程集团有限公司（中土集团）承建的埃塞俄比亚莫焦旱港扩建项目10日在莫焦市竣工，将有力提升埃塞货物运输效率并降低物流成本。 埃塞俄比亚总理阿比在竣工仪式上表示，近年来埃塞经济社会实现快速发展，物流业作出了重要贡献，但对于埃塞这样一个内陆国家，物流成本依然太高，导致进口货物价格居高不下。莫焦旱港扩建后将有力提升货物吞吐量和运输效率。 中国驻埃塞俄比亚大使馆临时代办孙明晰说，该项目是亚吉…",
    "content": "新华社亚的斯亚贝巴9月10日电（记者刘方强）由中国土木工程集团有限公司（中土集团）承建的埃塞俄比亚莫焦旱港扩建项目10日在莫焦市竣工，将有力提升埃塞货物运输效率并降低物流成本。 埃塞俄比亚总理阿比在竣工仪式上表示，近年来埃塞经济社会实现快速发展，物流业作出了重要贡献，但对于埃塞这样一个内陆国家，物流成本依然太高，导致进口货物价格居高不下。莫焦旱港扩建后将有力提升货物吞吐量和运输效率。 中国驻埃塞俄比亚大使馆临时代办孙明晰说，该项目是亚吉铁路重要配套设施，亚吉铁路承担埃塞大量国际货物贸易运输。中方同埃方正在推进亚吉铁…"
