    "content": "新华社南京9月10日电 题：从倡议到行动，打击电信网络诈骗有了新平台 新华社记者李明辉、朱国亮 作为加强打击电信网络诈骗国际合作的重要标志，国际打击电信网络诈骗联盟9月10日在江苏连云港成立。这一政府间国际组织因何而生？又将如何推动各国更好协同作战清除电诈毒瘤？记者展开了采访。 “跨国电诈犯罪已成为世界公害和全球性打击治理难题。”全球公共安全合作论坛（连云港）2026年大会主席曾伟雄说，今年大会期间成立国际打击电信网络诈骗联盟，目的是凝聚共识，并将共识转化为国际行动。 当前，电诈犯罪仍在全球继续蔓延扩散。随着东南亚…"
