    "content": "新华社北京9月10日电 题：全力救治善后 深入排查隐患——各地各部门贯彻落实习近平总书记重要指示精神坚决守牢安全发展底线 新华社记者 9月10日11时15分许，山东青岛市北海造船有限公司一艘外籍货轮靠港维修期间起火，造成重大人员伤亡。 事故发生后，习近平总书记高度重视并作出重要指示，要求“抓紧搜救失联人员，妥善做好善后安抚等工作”“尽快查明事故原因，依法严肃追究责任”“各地区各有关部门要深刻汲取教训，深入排查整治各类火灾隐患，落实落细防范措施，坚决遏制重特大事故发生”。 事故突发，情况紧急。相关地方和部门坚决贯彻落…"
