    "title": "伦敦股市10日下跌",
    "link": "http://www.news.cn/20260911/87131bba5bf24707b876d07f8d6a6b02/c.html",
    "pub_date": "2026-09-11 01:20:20",
    "author": "张亚东",
    "description": "新华社伦敦9月10日电（记者张亚东）英国伦敦股市《金融时报》100种股票平均价格指数10日报收于10608.92点，较前一交易日下跌61.14点，跌幅为0.57%。欧洲三大股指当天全线下跌。 当天伦敦股市成分股中位于涨幅前五位的个股分别为：烟草集团帝国品牌公司股价上涨1.84%，英美烟草股价上涨1.54%，沃达丰集团股价上涨1.46%，英国石油股价上涨1.44%，餐饮服务公司金巴斯集团股价上涨1.41%。 当天伦敦股市成分股中位于跌幅前…",
    "content": "新华社伦敦9月10日电（记者张亚东）英国伦敦股市《金融时报》100种股票平均价格指数10日报收于10608.92点，较前一交易日下跌61.14点，跌幅为0.57%。欧洲三大股指当天全线下跌。 当天伦敦股市成分股中位于涨幅前五位的个股分别为：烟草集团帝国品牌公司股价上涨1.84%，英美烟草股价上涨1.54%，沃达丰集团股价上涨1.46%，英国石油股价上涨1.44%，餐饮服务公司金巴斯集团股价上涨1.41%。 当天伦敦股市成分股中位于跌幅前五位的个股分别为：英国联合食品集团股价下跌7.92%，矿业公司安托法加斯塔股价下…"
