    "author": "陈刚,刘白云",
    "description": "新华社雅典9月10日电（记者陈刚、刘白云）2026年达喀尔青年奥林匹克运动会圣火采集和交接仪式10日上午在希腊首都雅典的泛雅典体育场举行。奥运圣火被正式移交给达喀尔青奥会组委会，开启前往非洲大陆首个奥林匹克赛事举办地塞内加尔的旅程。 图片来自国际奥委会官网 当天的仪式以希腊和塞内加尔两国文化和体育表演拉开序幕。来自希腊的拉拉队以活力四射的街舞和健身操点燃现场气氛；塞内加尔歌手基娅·卢姆的歌声浑厚有力，展现出鲜明的非洲音乐特色。在现代奥林…",
    "content": "新华社雅典9月10日电（记者陈刚、刘白云）2026年达喀尔青年奥林匹克运动会圣火采集和交接仪式10日上午在希腊首都雅典的泛雅典体育场举行。奥运圣火被正式移交给达喀尔青奥会组委会，开启前往非洲大陆首个奥林匹克赛事举办地塞内加尔的旅程。 图片来自国际奥委会官网 当天的仪式以希腊和塞内加尔两国文化和体育表演拉开序幕。来自希腊的拉拉队以活力四射的街舞和健身操点燃现场气氛；塞内加尔歌手基娅·卢姆的歌声浑厚有力，展现出鲜明的非洲音乐特色。在现代奥林匹克运动的发源地，这些节目象征着不同文化、不同国家和不同青年群体之间的相遇。 随…"
