    "pub_date": "2026-09-11 00:17:02",
    "author": "胡心懿,俞菀,郑可意,崔力,徐卓宇",
    "description": "循星而来，托举成长，守望发光。无数特殊教育教师深耕一线，把专业与耐心包裹进每一段与孩子们相处的日常中，陪伴那些走得慢一些的孩子，迈向属于自己的远方。 第42个教师节到来之际，谨以此片献给那些一路循星而来、守得星光渐亮的特殊教育教师群体。 记者：胡心懿、俞菀、郑可意、崔力、徐卓宇 特别鸣谢：浙江省平湖市实验小学教育集团黄姑实验学校、杭州市紫云实验学校、杭州市杨绫子学校 新华社音视频部 新华社浙江分社 联合制作",
    "content": "循星而来，托举成长，守望发光。无数特殊教育教师深耕一线，把专业与耐心包裹进每一段与孩子们相处的日常中，陪伴那些走得慢一些的孩子，迈向属于自己的远方。 第42个教师节到来之际，谨以此片献给那些一路循星而来、守得星光渐亮的特殊教育教师群体。 记者：胡心懿、俞菀、郑可意、崔力、徐卓宇 特别鸣谢：浙江省平湖市实验小学教育集团黄姑实验学校、杭州市紫云实验学校、杭州市杨绫子学校 新华社音视频部 新华社浙江分社 联合制作"
