    "content": "新华社达喀尔9月10日电（记者陈晨 齐琪）巴马科消息：马里军方10日说，今年8月，马里武装部队在全国多个战区开展军事行动，打死约1000名恐怖分子。 马里武装部队新闻与公共关系局局长马伊加当天在首都巴马科举行的新闻发布会上说，马里空军8月共实施了214次空中打击，摧毁50处恐怖组织基地、564辆摩托车和129辆皮卡车。马里军方还摧毁5处恐怖分子藏身点，并夺回一处被恐怖分子占据的手工采金点。 自2012年以来，马里安全局势持续动荡，恐怖袭击、武装冲突和族群暴力事件频发。近年来，马里军方多次表示将持续打击境内恐怖主义和…"
