    "content": "9月8日，纳米比亚当地舞蹈团体在温得和克举行的\"中纳文化庙会\"上表演传统舞蹈。新华社发（穆萨·卡塞凯摄摄） 新华社温得和克9月10日电 通讯｜琵琶邂逅非洲鼓——文化庙会走进温得和克 新华社记者林晶 郭轶凡 丝弦流转，中国乐手指尖轻拨，琵琶曲声时而婉转悠扬、时而热烈奔涌；鼓点欢腾，纳米比亚卡万戈舞者踏节登场，带来热情炽烈的部族律动。 由中国驻纳米比亚大使馆主办，纳米比亚教育、创新、青年、体育、艺术与文化部协办的“中纳文化庙会”日前在温得和克举行。中纳两国人士欢聚一堂，体验中国传统趣味游戏、欣赏歌舞表演，共同参与这场文…"
