    "description": "金砖国家领导人第十八次会晤将在印度新德里举行。 印度是世界四大文明古国之一，是南亚次大陆最大国家，与中国、尼泊尔、不丹、缅甸、孟加拉国和巴基斯坦交界，濒临孟加拉湾和阿拉伯海。 印度总人口约14.6亿，有100多个民族，其中印度斯坦族约占总人口的46.3%。印地语和英语同为官方语言。首都为新德里。 新华社音视频部制作",
