    "description": "新华社天津9月10日电（记者彭韵佳、张建新）医用耗材“团购清单”再拓新领域。第七批国家组织高值医用耗材集中带量采购9月10日在天津开标，成功采购23种消化介入类耗材，148家企业517个产品拟中标。 至此，国家组织高值医用耗材集采已覆盖165种耗材。此次集采聚焦消化内镜手术里形形色色的微型耗材，从“小”耗材里挤出的“大”实惠，正一笔笔算进患者的账单里。 ——临床主流产品尽数纳入。 圈套器、各类支架、取石网篮、止血夹……这些小巧的器械是日…",
    "content": "新华社天津9月10日电（记者彭韵佳、张建新）医用耗材“团购清单”再拓新领域。第七批国家组织高值医用耗材集中带量采购9月10日在天津开标，成功采购23种消化介入类耗材，148家企业517个产品拟中标。 至此，国家组织高值医用耗材集采已覆盖165种耗材。此次集采聚焦消化内镜手术里形形色色的微型耗材，从“小”耗材里挤出的“大”实惠，正一笔笔算进患者的账单里。 ——临床主流产品尽数纳入。 圈套器、各类支架、取石网篮、止血夹……这些小巧的器械是日常的胃肠镜检查，以及息肉切除、消化道止血、结石取出等内镜微创手术的关键工具。 过…"
