    "author": "齐菲,宋晨",
    "description": "新华社澳门9月10日电 澳门金融管理局10日表示，深圳市人民政府当日成功在澳门发行10亿元（人民币，下同）地方政府债券。这是深圳市继去年后第二年在澳门发行离岸人民币地方政府债券，首次在澳门发行大湾区主题可持续发展债券。 据介绍，本次深圳市地方政府债券面向专业投资者发行，总发行规模为10亿元，期限为3年，发行利率定价为1.41%，募集资金将用于水治理、医疗卫生等项目，并已获得香港品质保证局发出发行前阶段认证证书。本次地方政府债券的发行受到…",
    "content": "新华社澳门9月10日电 澳门金融管理局10日表示，深圳市人民政府当日成功在澳门发行10亿元（人民币，下同）地方政府债券。这是深圳市继去年后第二年在澳门发行离岸人民币地方政府债券，首次在澳门发行大湾区主题可持续发展债券。 据介绍，本次深圳市地方政府债券面向专业投资者发行，总发行规模为10亿元，期限为3年，发行利率定价为1.41%，募集资金将用于水治理、医疗卫生等项目，并已获得香港品质保证局发出发行前阶段认证证书。本次地方政府债券的发行受到市场关注，获得超额认购。 澳门金融管理局祝贺债券的成功发行，并感谢国家财政部与深…"
