    "content": "9月10日，第十六次亚太经合组织能源部长会议在北京开幕，中共中央政治局常委、国务院副总理丁薛祥出席并致辞。新华社记者刘卫兵摄 新华社北京9月10日电 第十六次亚太经合组织能源部长会议10日在北京开幕，中共中央政治局常委、国务院副总理丁薛祥出席并致辞。 丁薛祥指出，在习近平主席“四个革命、一个合作”能源安全新战略指引下，中国能源供给能力持续增强，绿色低碳转型深入推进，新能源产业快速成长壮大，能源高质量发展取得显著成效。中国深度参与亚太经合组织框架内能源务实合作，有力促进区域能源发展，为维护全球能源安全作出重要贡献。 …"
