    "author": "欧东衢,吴思,娄琛",
    "description": "这是2025年拍摄的修缮后的贵州省安顺市云山屯一处房屋。新华社发 新华社贵阳9月10日电 题：守护古老屯堡：中法遗产保护者携手同行 新华社记者欧东衢、吴思 今年夏天，在中国西南部贵州省安顺市云山屯，一群来自法国的学生、企业家和建筑师拿起修缮工具，与当地工匠一起拆除旧瓦、清理墙体、搬运木梁，共同修缮一栋已有数百年历史的老屋。 过去十多年里，几乎每到夏季，国际志愿者都会来到云山屯，参与当地传统建筑保护。云山屯是贵州众多屯堡聚落之一。600多…",
    "content": "这是2025年拍摄的修缮后的贵州省安顺市云山屯一处房屋。新华社发 新华社贵阳9月10日电 题：守护古老屯堡：中法遗产保护者携手同行 新华社记者欧东衢、吴思 今年夏天，在中国西南部贵州省安顺市云山屯，一群来自法国的学生、企业家和建筑师拿起修缮工具，与当地工匠一起拆除旧瓦、清理墙体、搬运木梁，共同修缮一栋已有数百年历史的老屋。 过去十多年里，几乎每到夏季，国际志愿者都会来到云山屯，参与当地传统建筑保护。云山屯是贵州众多屯堡聚落之一。600多年前，明代军士及家属在这里驻守、屯田，逐渐形成被称为“屯堡”的石头村寨。在这里，…"
