    "description": "从教32年，湖北省咸宁市崇阳县的王值军，自掏腰包造船，28年划船接送库区孩子上下学。 2024年教学点合并，他明明有机会去县城教书，却依旧选择留在乡里。这到底为了什么？近日，记者在崇阳县高枧乡中山小学，再次见到了这位大山里的“船夫老师”。 作者：罗兰、沈庭萱 新华社音视频部制作",
