    "pub_date": "2026-09-10 21:57:39",
    "author": "",
    "description": "中新社北京9月10日电 (记者 孙自法)记者10日从中国科学院青藏高原研究所大陆碰撞隆升及影响团队获悉，该团队领衔中外合作者，对形成年龄约2.6亿年的攀枝花白马矿区层状辉长岩开展系列研究，最新发现当时古地磁场强度为现代地磁场的约51%。",
    "content": "中新社北京9月10日电 (记者 孙自法)记者10日从中国科学院青藏高原研究所大陆碰撞隆升及影响团队获悉，该团队领衔中外合作者，对形成年龄约2.6亿年的攀枝花白马矿区层状辉长岩开展系列研究，最新发现当时古地磁场强度为现代地磁场的约51%。"
