    "author": "王思北",
    "description": "新华社北京9月10日电（王思北、李旺熹）记者10日从中国杂技家协会获悉，第十二届中国杂技金菊奖全国杂技比赛暨第六届中国杂技艺术节将于9月13日至19日在河南濮阳举办。本届金菊奖将从入围决赛的26个节目中，评选出10个杂技节目奖。 本次活动以“技通古今·艺耀五洲”为主题，涵盖开闭幕式、中国杂技金菊奖全国杂技比赛、全国优秀杂技剧目展演、世界马戏交流对话、杂技艺术传承创新研讨会、惠民演出等多项活动，将汇聚全国顶尖杂技院团和优秀人才，展演一批杂…",
    "content": "新华社北京9月10日电（王思北、李旺熹）记者10日从中国杂技家协会获悉，第十二届中国杂技金菊奖全国杂技比赛暨第六届中国杂技艺术节将于9月13日至19日在河南濮阳举办。本届金菊奖将从入围决赛的26个节目中，评选出10个杂技节目奖。 本次活动以“技通古今·艺耀五洲”为主题，涵盖开闭幕式、中国杂技金菊奖全国杂技比赛、全国优秀杂技剧目展演、世界马戏交流对话、杂技艺术传承创新研讨会、惠民演出等多项活动，将汇聚全国顶尖杂技院团和优秀人才，展演一批杂技精品力作，集中展现新时代我国杂技艺术创作最新成果。 据悉，中国杂技金菊奖是全国…"
