    "content": "更适配工业场景的大模型，助力机器人迭代的高质量训练数据集，可将设备、产线、工厂全域打通的智能互联体系…… 2026全球工业互联网大会9月8日至10日在辽宁沈阳举行。记者在会上采访了解到，一批面向制造一线的新技术、新方案集中亮相，AI（人工智能）赋能下的工业互联网，不仅把设备连上网，也能够替工厂“动脑筋”，制造业智能化改造、数字化转型呈现新亮点。 提到工业数字化，人们往往容易想到设备联网、数据上云。如今，这样的探索更进一步：系统能根据订单、库存、设备状态自己排产。越来越多的机器不光会干活，还开始会“拿主意”。 8月2…"
