    "author": "王镜宇,林德韧",
    "description": "新华社北京9月10日电（记者王镜宇、林德韧）根据10日下发的《中国篮球协会关于印发2027年职业联赛升降级办法和竞赛规程的通知》（以下简称《通知》），2027年4月将举行中国篮球协会职业联赛升降级附加赛，这意味着CBA联赛（中国男子篮球职业联赛）将恢复取消了20余年的升降级制度。 根据这份《通知》，2027年职业联赛升降级的进程分为赛前评估、附加赛、赛后评估和结果公布共4个阶段。通过赛前评估的2026-2027赛季CBA联赛常规赛排名后…",
