    "title": "日本航空自卫队一战机因故障紧急降落",
    "link": "http://www.news.cn/20260910/5c61af5efbab4141ac6c36f9b296ee7f/c.html",
    "pub_date": "2026-09-10 21:34:34",
    "author": "李子越,陈泽安",
    "description": "新华社东京9月10日电（记者李子越 陈泽安）据日本共同社报道，日本航空自卫队一架战斗机10日晚在冲绳县那霸机场因故障紧急降落。 报道引述日本国土交通省那霸机场事务所消息称，当地时间10日19时15分，航空自卫队一架F-15战斗机在该机场紧急降落，其所在跑道一度被关闭。民航客机被迫使用机场另一跑道起降。 航空自卫队那霸基地称，10日18时5分左右，这架战斗机在飞行过程中发生液压系统故障，随后在那霸机场降落。 那霸机场方面称，战斗机着陆时未…",
    "content": "新华社东京9月10日电（记者李子越 陈泽安）据日本共同社报道，日本航空自卫队一架战斗机10日晚在冲绳县那霸机场因故障紧急降落。 报道引述日本国土交通省那霸机场事务所消息称，当地时间10日19时15分，航空自卫队一架F-15战斗机在该机场紧急降落，其所在跑道一度被关闭。民航客机被迫使用机场另一跑道起降。 航空自卫队那霸基地称，10日18时5分左右，这架战斗机在飞行过程中发生液压系统故障，随后在那霸机场降落。 那霸机场方面称，战斗机着陆时未引发火灾，机体目前已从跑道上移走。 据当地媒体报道，8月18日，另一架航空自卫队…"
