    "content": "9月10日，在白俄罗斯明斯克，校方为中国—白俄罗斯卓越工程师学院首届学员代表发放院系服装。新华社发（任科夫摄） 新华社明斯克9月10日电（记者陈汀）中国—白俄罗斯卓越工程师学院首个学年开学典礼10日在白俄罗斯国立技术大学举行。 中国驻白俄罗斯大使馆公使衔参赞宋艳萍在开学典礼上致辞说，作为两国教育领域合作的又一标志性成果，中白卓越工程师学院的建立是两国在工程教育领域探索“共商共建共享”模式的重要实践，是一体推进教育科技人才发展，深化产教融合、校企协同、跨境共育的重要尝试。希望学院未来成为两国工程教育交流、人才联合培养…"
