    "content": "新华社北京9月10日电 题：华西秋雨为何备受关注 新华社记者刘诗平 打开中央气象台10日的全国降水量预报图，全国大部地区天气晴好，但华西地区普遍是下雨天，未来72小时全国降水量预报图显示了同样的趋势。这是否意味着华西秋雨已经开启？今年华西秋雨的雨量和影响如何？华西秋雨监测为何非常重要？新华社记者对此采访了相关气象专家。 何为华西秋雨 在我国，一个时段连绵不断的雨，除了夏天江南地区和长江中下游的梅雨，就是秋天下在华西地区的华西秋雨。 像监测梅雨哪一天入梅和出梅一样，气象部门对华西秋雨也制定了相应的监测标准：时间上集中…"
