    "content": "中新网山东青岛9月10日电(胡耀杰 张孝鹏 王禹) 2026年9月10日11时15分许，一外籍货船在中国船舶集团青岛北海造船有限公司检修过程中发生火情。船上共有42人，其中，12人安全撤出；5人受伤送医(目前生命体征平稳)；25人失联。截至9月10日19时24分，25名失联人员全部找到，均无生命体征。(完)"
