    "description": "新华社天津9月10日电 中共中央政治局委员、国务院副总理何立峰10日在天津出席矿业国际合作部长论坛暨2026中国国际矿业大会开幕式并致辞。 何立峰指出，近年来，在习近平主席提出的构建人类命运共同体理念的科学指引下，中国政府深入推进全球矿业合作，以实际行动践行四大全球倡议，探索出一条开放包容、合作共赢的高质量发展之路，与各国建立了相互尊重、和平共处、互利共赢的良好合作关系，共同取得了丰硕成果。 何立峰指出，矿业国际合作是实现各国资源优势互…",
    "content": "新华社天津9月10日电 中共中央政治局委员、国务院副总理何立峰10日在天津出席矿业国际合作部长论坛暨2026中国国际矿业大会开幕式并致辞。 何立峰指出，近年来，在习近平主席提出的构建人类命运共同体理念的科学指引下，中国政府深入推进全球矿业合作，以实际行动践行四大全球倡议，探索出一条开放包容、合作共赢的高质量发展之路，与各国建立了相互尊重、和平共处、互利共赢的良好合作关系，共同取得了丰硕成果。 何立峰指出，矿业国际合作是实现各国资源优势互补、促进经济社会发展的重要载体，也是维护全球产供链安全稳定的现实需要。中国始终充…"
