    "author": "",
    "description": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 2013年以来，习近平主席多次主持或出席金砖国家领导人会晤，在多个场合就深化金砖国家在各领域务实合作作出一系列生动阐述，引领推动金砖国家合作机制不断发展。 文案：郭洁宇 张海磊 设计：潘红宇 新华社新媒体中心制作 新华社出品",
    "content": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 2013年以来，习近平主席多次主持或出席金砖国家领导人会晤，在多个场合就深化金砖国家在各领域务实合作作出一系列生动阐述，引领推动金砖国家合作机制不断发展。 文案：郭洁宇 张海磊 设计：潘红宇 &nbsp; 新华社新媒体中心制作 新华社出品"
