    "description": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 经各方共同努力，金砖合作机制已成为当今世界最重要的新兴市场国家和发展中国家团结合作平台。作为这一机制的坚定支持者和参与者，中国始终秉持开放包容、合作共赢的金砖精神，积极贡献中国智慧与方案，同金砖伙伴在发展振兴的道路上携手同行。 习近平主席此次出席金砖国家领导人会晤，将同各方一道擘画“大金砖合作”高质量发展蓝图，汇聚全球南方联合自强…",
    "content": "应印度共和国总理莫迪邀请，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。 经各方共同努力，金砖合作机制已成为当今世界最重要的新兴市场国家和发展中国家团结合作平台。作为这一机制的坚定支持者和参与者，中国始终秉持开放包容、合作共赢的金砖精神，积极贡献中国智慧与方案，同金砖伙伴在发展振兴的道路上携手同行。 习近平主席此次出席金砖国家领导人会晤，将同各方一道擘画“大金砖合作”高质量发展蓝图，汇聚全球南方联合自强的强大力量，为动荡变革的世界注入更多稳定性与正能量。 引领金砖建设之路 2013…"
