    "content": "当前我国城市发展正从大规模增量扩张阶段转向存量提质增效为主的阶段，城市更新事关民生福祉，关乎城市品质提升，也为建筑业转型提供广阔机遇。在2026年服贸会工程咨询与建筑服务专题展，各展台突出展示城市更新实践。一批老旧楼宇改造、片区统筹更新方案也不再是“点上创新”，而是可复制、可推广的“连片风景”。 低效楼宇盘活利用是政策所向、民生所需。中建二局装饰公司带来的，于2025年全面入住的北京西城区礼士居改造项目引起与会嘉宾关注。项目指挥长娄茂源滑动手机里的老照片告诉记者，这里原为1976年建成的老厂房，先后用作印刷厂、办公…"
