    "pub_date": "2026-09-10 20:54:37",
    "author": "",
    "description": "金砖国家人口占世界近一半，不同文明包容共存、交流互鉴。在金砖国家领导人第十八次会晤即将举行之际，让我们定格“金砖大家庭”的人文之光，共赏多元文化之美。 2025年，马来西亚、泰国、越南、白俄罗斯、玻利维亚、古巴、哈萨克斯坦、乌兹别克斯坦、乌干达、尼日利亚成为金砖伙伴国。 摄影：王建华、毕晓洋、姚大伟、鞠焕宗、李明、郝建伟、沙达提、辛梦晨、谢剑飞、李梦馨、邬惠我、韩旭、刘颍、伊恩·托马斯、阿贡、拉亨、任科夫、阿佳拉·纳瓦达、华金·埃尔南德…",
    "content": "金砖国家人口占世界近一半，不同文明包容共存、交流互鉴。在金砖国家领导人第十八次会晤即将举行之际，让我们定格“金砖大家庭”的人文之光，共赏多元文化之美。 2025年，马来西亚、泰国、越南、白俄罗斯、玻利维亚、古巴、哈萨克斯坦、乌兹别克斯坦、乌干达、尼日利亚成为金砖伙伴国。 摄影：王建华、毕晓洋、姚大伟、鞠焕宗、李明、郝建伟、沙达提、辛梦晨、谢剑飞、李梦馨、邬惠我、韩旭、刘颍、伊恩·托马斯、阿贡、拉亨、任科夫、阿佳拉·纳瓦达、华金·埃尔南德斯 设计：崔文、赖思雨 编辑：伍婧丹、白雪骐、单宇琦、张帆、戴翘楚、李旭伦"
