    "description": "中新网乌鲁木齐9月10日电 (记者 苟继鹏)新疆维吾尔自治区人民政府新闻办公室10日举行新闻发布会，介绍新疆“十五五”时期打造全国优质农牧产品重要供给基地、扎实推进乡村全面振兴有关情况。记者在会上获悉，到“十五五”末，新疆将基本建成全国优质农牧产品重要供给基地。",
